@mkouba I was able to reproduce it with:

```
package io.quarkus.vertx.core.deployment;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.concurrent.atomic.AtomicReference;

import javax.enterprise.context.ApplicationScoped;
import javax.enterprise.event.Observes;
import javax.inject.Inject;

import org.jboss.shrinkwrap.api.ShrinkWrap;
import org.jboss.shrinkwrap.api.spec.JavaArchive;
import org.junit.jupiter.api.RepeatedTest;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.RegisterExtension;

import io.quarkus.arc.Arc;
import io.quarkus.runtime.StartupEvent;
import io.quarkus.test.QuarkusUnitTest;
import io.vertx.core.Vertx;

public class VertxInjectionTest {

    @RegisterExtension
    static final QuarkusUnitTest config = new QuarkusUnitTest()
            .setArchiveProducer(() -> ShrinkWrap.create(JavaArchive.class)
                    .addClasses(MyBean.class));

    @RepeatedTest(1000)
    public void test() {
        MyBean bean = Arc.container().instance(MyBean.class).get();
        assertThat(bean.get()).isNotNull();
    }

    @ApplicationScoped
    public static class MyBean extends AtomicReference<Vertx> {

        @Inject
        Vertx vertx;

        public void init(@Observes StartupEvent ev) {
            assertThat(vertx).isNotNull();
            set(vertx);
        }
    }
}
```
